type Key=typeof rows[number][0];
const column=(index:number):Record<Key,Message>=>{
 const values=Object.fromEntries(rows.map(row=>[row[0],row[index]])) as Record<Key,Message>;
 if(index===1){values['items.count']={one:'{count} item',other:'{count} items'};values['design.count']={one:'{count} design',other:'{count} designs'};}
 if(index===3){values['items.count']={one:'{count} article',other:'{count} articles'};values['design.count']={one:'{count} création',other:'{count} créations'};}
 if(index===5){values['items.count']={one:'{count} товар',few:'{count} товара',many:'{count} товаров',other:'{count} товара'};values['design.count']={one:'{count} дизайн',few:'{count} дизайна',many:'{count} дизайнов',other:'{count} дизайна'};}
 if(index===6){values['items.count']={one:'{count} artículo',other:'{count} artículos'};values['design.count']={one:'{count} diseño',other:'{count} diseños'};}
 return values;
};
export const commerceMessages=defineCatalogue({en:column(1),sw:column(2),fr:column(3),'zh-Hans':column(4),ru:column(5),es:column(6)});
export type CommerceIssue={key:keyof typeof commerceMessages.en;values?:MessageValues};
// Untrusted API/provider text never becomes a translated key or a visible sentence.
export const checkoutIssueCodes:Readonly<Record<string,CommerceIssue['key']>>=Object.freeze({
 attempt_request_conflict:'checkout.attemptConflict',invalid_phone_use_254:'checkout.invalidPhone',
 out_of_stock:'checkout.outOfStock',insufficient_inventory:'checkout.outOfStock',variant_out_of_stock:'checkout.outOfStock',
});
